# Fixed action: robust detection with fallback to sliding_window_detection and safe checks.
try:
    # Try the primary detection first
    image_1_detection, image_1_boxes = detection(image_1, ["measuring cup", "cup", "glass"])
    if image_1_detection is not None:
        display(image_1_detection.annotated_image)
    print("Detected boxes from detection():", image_1_boxes)
except Exception as e:
    print("detection() raised an exception:", repr(e))
    image_1_detection = None
    image_1_boxes = []

# If detection found boxes, zoom into the first one
if image_1_boxes:
    try:
        box = image_1_boxes[0]
        zoomed = zoom_in_image_by_bbox(image_1, box, padding=0.05)
        display(zoomed)
    except Exception as e:
        print("Error while zooming into detection box:", repr(e))
else:
    # Fallback: use sliding window search to find small objects
    print("No boxes found from detection() — trying sliding_window_detection() as a fallback...")
    try:
        possible_patches, possible_boxes = sliding_window_detection(image_1, ["measuring cup", "cup", "glass"])
        # Display patches (if any)
        if possible_patches:
            for i, patch in enumerate(possible_patches):
                print(f"Patch {i}:")
                display(patch.annotated_image)
            # Find first patch that contains boxes
            found = False
            for i, boxes in enumerate(possible_boxes):
                if boxes:
                    found = True
                    chosen_patch = possible_patches[i]
                    chosen_box = boxes[0]
                    print(f"Zooming into first detected box in patch {i}: {chosen_box}")
                    try:
                        zoomed = zoom_in_image_by_bbox(chosen_patch.original_image, chosen_box, padding=0.05)
                        display(zoomed)
                    except Exception as e:
                        print("Error while zooming into sliding-window box:", repr(e))
                    break
            if not found:
                print("Sliding window did not detect the measuring cup either.")
        else:
            print("sliding_window_detection() returned no patches.")
    except Exception as e2:
        print("sliding_window_detection() raised an exception:", repr(e2)))
```

